    diagonal_pairs = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2 - r1) == abs(c2 - c1) and r2 != r1:
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                diagonal_pairs.append((r1, c1, dr, dc))
                for k in range(1, abs(r2 - r1)):
                    paint(r1 + dr * k, c1 + dc * k, 1)

    # A six on one of those diagonal lines sends a six-colored line
    # along the perpendicular diagonal, continuing to the grid edges.
    for r, c in sixes:
        for r1, c1, dr, dc in diagonal_pairs:
            if (r - r1) * dc == (c - c1) * dr:
                # Perpendicular diagonal direction has opposite row/col signs.
                for sr, sc in ((1, -1), (-1, 1)):
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w:
                        paint(rr, cc, 6)
                        rr += sr
                        cc += sc
                break

    return out
